#![cfg(test)]

use rstest::rstest;

use super::class::Class;
use super::{ErrorFacts, Normalizer};
use crate::rate_limit::RateLimitDimension;

struct Case {
    facts: ErrorFacts,
    present: bool,
    expected: Option<&'static str>,
}

#[rstest]
#[case::proxy_type_first(Case { present: true, facts: ErrorFacts { proxy_type: Some("budget_exceeded".to_owned()), message: "ordinary".to_owned(), class: Class::Timeout, status_code: Some(408), rate_limit_type: None }, expected: Some("429_BUDGET_EXCEEDED") })]
#[case::message_before_class(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "the request timed out".to_owned(), class: Class::BadRequestError, status_code: Some(400), rate_limit_type: None }, expected: Some("408_UPSTREAM_TIMEOUT") })]
#[case::budget_rate_limit(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "rate limited".to_owned(), class: Class::RateLimitError, status_code: Some(429), rate_limit_type: Some(RateLimitDimension::Budget) }, expected: Some("429_BUDGET_EXCEEDED") })]
#[case::vendor_rate_limit(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "rate limited".to_owned(), class: Class::RateLimitError, status_code: Some(429), rate_limit_type: Some(RateLimitDimension::Requests) }, expected: Some("429_RATE_LIMIT_EXCEEDED") })]
#[case::class_before_router_wrapper(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "no fallback model group found".to_owned(), class: Class::AuthenticationError, status_code: Some(500), rate_limit_type: None }, expected: Some("401_AUTHENTICATION_FAILED") })]
#[case::status_fallback(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "other".to_owned(), class: Class::Other, status_code: Some(502), rate_limit_type: None }, expected: Some("500_PROVIDER_INTERNAL_ERROR") })]
#[case::unclassified(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "other".to_owned(), class: Class::Other, status_code: Some(418), rate_limit_type: None }, expected: Some("UNCLASSIFIED") })]
#[case::absent_exception(Case { present: false, facts: ErrorFacts { proxy_type: None, message: "other".to_owned(), class: Class::Other, status_code: None, rate_limit_type: None }, expected: None })]
#[case::budget_phrase(Case { present: true, facts: ErrorFacts { proxy_type: None, message: "budget has been exceeded".to_owned(), class: Class::Other, status_code: Some(418), rate_limit_type: None }, expected: Some("429_BUDGET_EXCEEDED") })]
